CREATE SCHEMA IF NOT EXISTS alrifai;
SET search_path TO alrifai,public;
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, sha256 TEXT NOT NULL, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','viewer')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE login_attempts(identity TEXT NOT NULL,attempted_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX login_attempts_identity_time ON login_attempts(identity,attempted_at);
CREATE TABLE sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('file','whatsapp_mcp','hermes','manual')),config JSONB NOT NULL DEFAULT '{}',token_hash TEXT UNIQUE,enabled BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE source_files(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),name TEXT NOT NULL,mime TEXT NOT NULL,sha256 TEXT NOT NULL,content BYTEA NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_id,sha256));
CREATE TABLE import_runs(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),file_id TEXT REFERENCES source_files(id),status TEXT NOT NULL CHECK(status IN('pending','complete','failed')),counts JSONB NOT NULL DEFAULT '{}',error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,UNIQUE(source_id,file_id));
CREATE TABLE messages(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),external_id TEXT NOT NULL,chat_id TEXT NOT NULL,conversation_type TEXT NOT NULL CHECK(conversation_type IN('direct','group')),sender_phone TEXT,receiver_phone TEXT,sent_at TIMESTAMPTZ NOT NULL,body TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}',file_id TEXT REFERENCES source_files(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_id,external_id));
CREATE INDEX messages_chat_date ON messages(source_id,chat_id,sent_at);
CREATE TABLE employees(id TEXT PRIMARY KEY,identity_mobile TEXT NOT NULL UNIQUE CHECK(identity_mobile ~ '^8801[3-9][0-9]{8}$'),display_name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE records(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('program','transaction','vessel','project')),payload JSONB NOT NULL,business_key TEXT,employee_id TEXT REFERENCES employees(id),amount_cents BIGINT CHECK(amount_cents>0),source_id TEXT REFERENCES sources(id),revision INTEGER NOT NULL DEFAULT 1,deleted_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX records_business_identity ON records(kind,business_key) WHERE deleted_at IS NULL AND business_key IS NOT NULL;
CREATE INDEX records_kind_active ON records(kind,deleted_at);
CREATE INDEX records_payload ON records USING GIN(payload);
CREATE TABLE record_evidence(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES records(id),message_id TEXT REFERENCES messages(id),file_id TEXT REFERENCES source_files(id),details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews(id TEXT PRIMARY KEY,kind TEXT NOT NULL,source_id TEXT REFERENCES sources(id),message_id TEXT REFERENCES messages(id),file_id TEXT REFERENCES source_files(id),candidate JSONB,existing_record_id TEXT REFERENCES records(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','linked','accepted','dismissed')),resolution JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_log(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE consumer_checkpoints(source_id TEXT PRIMARY KEY REFERENCES sources(id),cursor JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE VIEW programs AS SELECT id,payload->>'motherVessel' AS mother_vessel,payload->>'lighterVessel' AS lighter_vessel,payload->>'masterMobile' AS master_mobile,payload->>'escortName' AS escort_name,payload->>'escortMobile' AS escort_mobile,payload->>'startDate' AS start_date,payload->>'shift' AS start_shift,payload->>'endDate' AS end_date,payload->>'endShift' AS end_shift,payload->>'releasePoint' AS release_point,payload->>'destination' AS destination,payload->>'status' AS status,revision,deleted_at FROM records WHERE kind='program';
CREATE VIEW accounts_transactions AS SELECT id,employee_id,payload->>'employeePhone' AS employee_mobile,payload->>'payoutPhone' AS payout_mobile,payload->>'name' AS employee_name,payload->>'date' AS transaction_date,payload->>'method' AS method,amount_cents,payload->>'source' AS source,revision,deleted_at FROM records WHERE kind='transaction';
